1	package factsync
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"net/http"
8		"net/http/httptest"
9		"strings"
10		"testing"
11	)
12	
13	// A live round-trip against entire-api showed the drift these tests close: the server
14	// answers a violated cap with an actionable body —
15	//
16	//	400 {"title":"Bad Request","status":400,"detail":"branch is 600 bytes, limit is 512"}
17	//
18	// — and the client threw the body away, leaving the member with "unexpected status 400
19	// Bad Request": no statement of what was wrong and no statement of the limit.
20	//
21	// The other half of the fix is that improving the MESSAGE must not disturb the
22	// MEANING. Every status this transport reads is load-bearing control flow — 412/409
23	// is the CAS-loss signal the retry loops in sync.go and proposals.go key on, and
24	// 404/501/503 on the proposal endpoints is "this deployment has no queue", which
25	// degrades to the local queue instead of failing a sync whose facts already landed.
26	// So each surfacing test below has a sentinel test beside it, and the sentinel tests
27	// assert errors.Is, not the string.
28	
29	// serverDetail is the sentence the hosted API returns for the cap that exposed this.
30	const serverDetail = "branch is 600 bytes, limit is 512"
31	
32	const humaCapBody = `{"title":"Bad Request","status":400,"detail":"` + serverDetail + `"}`
33	
34	// statusServer answers every request with one status and one body.
35	func statusServer(t *testing.T, status int, body string) *httptest.Server {
36		t.Helper()
37		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
38			w.Header().Set("Content-Type", "application/json")
39			w.WriteHeader(status)
40			fmt.Fprint(w, body)
41		}))
42		t.Cleanup(srv.Close)
43		return srv
44	}
45	
46	// factsyncCalls is every method on HTTPServer that reads a status, keyed by name.
47	// Each returns only the error, because that is the whole of what a member sees when
48	// the server refuses.
49	var factsyncCalls = map[string]func(context.Context, *HTTPServer) error{
50		"Current": func(ctx context.Context, h *HTTPServer) error {
51			_, _, _, err := h.Current(ctx, "repo", "main")
52			return err
53		},
54		"Advance": func(ctx context.Context, h *HTTPServer) error {
55			_, err := h.Advance(ctx, "repo", "main", "old", []byte("fact:a\n"))
56			return err
57		},
58		"ListProposals": func(ctx context.Context, h *HTTPServer) error {
59			_, err := h.ListProposals(ctx, "repo", "main")
60			return err
61		},
62		"GetProposal": func(ctx context.Context, h *HTTPServer) error {
63			_, err := h.GetProposal(ctx, "repo", "main", "prop-1234567890abcdef")
64			return err
65		},
66		"PublishProposals": func(ctx context.Context, h *HTTPServer) error {
67			_, err := h.PublishProposals(ctx, "repo", "main", "old", nil)
68			return err
69		},
70		"ResolveProposal": func(ctx context.Context, h *HTTPServer) error {
71			_, err := h.ResolveProposal(ctx, ResolveProposalRequest{
72				RepoID: "repo", Branch: "main", ProposalID: "prop-1234567890abcdef",
73				Decision: Reject, FactsUnchanged: true,
74			})
75			return err
76		},
77	}
78	
79	// TestEveryFactsyncCallSurfacesTheServersObjection is the regression for the drift:
80	// on a 400 the member must read the server's own sentence, not just the status line.
81	func TestEveryFactsyncCallSurfacesTheServersObjection(t *testing.T) {
82		for name, call := range factsyncCalls {
83			t.Run(name, func(t *testing.T) {
84				srv := statusServer(t, http.StatusBadRequest, humaCapBody)
85				h := &HTTPServer{BaseURL: srv.URL, Token: "tok"}
86				err := call(context.Background(), h)
87				if err == nil {
88					t.Fatalf("%s: a 400 produced no error", name)
89				}
90				if !strings.Contains(err.Error(), serverDetail) {
91					t.Fatalf("%s: error = %q; want it to carry the server's own explanation %q", name, err, serverDetail)
92				}
93			})
94		}
95	}
96	
97	// A 5xx is read the same way — the surfacing is keyed on "not the success status",
98	// not on a hand-listed set of 4xx codes.
99	func TestFactsyncSurfacesA5xxObjection(t *testing.T) {
100		for name, call := range factsyncCalls {
101			t.Run(name, func(t *testing.T) {
102				srv := statusServer(t, http.StatusInternalServerError, `{"title":"Internal Server Error","detail":"fact-set store is read-only"}`)
103				h := &HTTPServer{BaseURL: srv.URL, Token: "tok"}
104				err := call(context.Background(), h)
105				if err == nil || !strings.Contains(err.Error(), "fact-set store is read-only") {
106					t.Fatalf("%s: error = %v; want the server's 500 explanation", name, err)
107				}
108			})
109		}
110	}
111	
112	// An ingress in front of entire-api answers with an HTML page, not JSON. The member
113	// must get its title, and the whole error must stay short enough to read.
114	func TestFactsyncNonJSONErrorPageIsBoundedAndReadable(t *testing.T) {
115		page := "<!DOCTYPE html>\n<html><head><title>504 Gateway Time-out</title></head><body>\n" +
116			strings.Repeat("<div>x</div>\n", 200000) + "</body></html>\n"
117		for name, call := range factsyncCalls {
118			t.Run(name, func(t *testing.T) {
119				srv := statusServer(t, http.StatusGatewayTimeout, page)
120				h := &HTTPServer{BaseURL: srv.URL, Token: "tok"}
121				err := call(context.Background(), h)
122				if err == nil {
123					t.Fatalf("%s: a 504 produced no error", name)
124				}
125				if !strings.Contains(err.Error(), "504 Gateway Time-out") {
126					t.Fatalf("%s: error = %q; want the page title", name, err)
127				}
128				if len(err.Error()) > 1024 {
129					t.Fatalf("%s: error is %d bytes; the HTML page was dumped at the member", name, len(err.Error()))
130				}
131				if strings.Contains(err.Error(), "<div>") {
132					t.Fatalf("%s: error = %q; raw markup reached the member", name, err)
133				}
134			})
135		}
136	}
137	
138	// SEMANTIC PRESERVATION 1/3 — 412 and 409 stay the CAS-loss signal.
139	//
140	// sync.go and proposals.go re-read and re-merge on errors.Is(err, ErrConflict). If the
141	// surfacing replaced that sentinel with a plain formatted error, a lost race would
142	// stop looking like a lost race and a converging sync would start failing instead.
143	func TestConflictStatusesStayErrConflict(t *testing.T) {
144		for _, status := range []int{http.StatusPreconditionFailed, http.StatusConflict} {
145			for _, body := range []string{"", `{"title":"Conflict","detail":"head moved to facts-abc"}`} {
146				name := fmt.Sprintf("%d/body=%d", status, len(body))
147				t.Run(name, func(t *testing.T) {
148					srv := statusServer(t, status, body)
149					h := &HTTPServer{BaseURL: srv.URL, Token: "tok"}
150	
151					if _, err := h.Advance(context.Background(), "repo", "main", "old", []byte("fact:a\n")); !errors.Is(err, ErrConflict) {
152						t.Fatalf("Advance(%d) = %v; want ErrConflict", status, err)
153					}
154					if _, err := h.PublishProposals(context.Background(), "repo", "main", "old", nil); !errors.Is(err, ErrConflict) {
155						t.Fatalf("PublishProposals(%d) = %v; want ErrConflict", status, err)
156					}
157					_, err := h.ResolveProposal(context.Background(), ResolveProposalRequest{
158						RepoID: "repo", Branch: "main", ProposalID: "prop-1234567890abcdef", Decision: Reject, FactsUnchanged: true,
159					})
160					if !errors.Is(err, ErrConflict) {
161						t.Fatalf("ResolveProposal(%d) = %v; want ErrConflict", status, err)
162					}
163					if body != "" && !strings.Contains(err.Error(), "head moved to facts-abc") {
164						t.Fatalf("ResolveProposal(%d) = %q; the server's explanation was dropped", status, err)
165					}
166				})
167			}
168		}
169	}
170	
171	// SEMANTIC PRESERVATION 2/3 — 404/501/503 on the proposal endpoints stay
172	// "this deployment has no queue", which facts_sync_cmd.go degrades on rather than
173	// failing a sync whose head-advance already succeeded.
174	func TestQueueUnsupportedStatusesStayUnsupported(t *testing.T) {
175		for _, status := range []int{http.StatusNotFound, http.StatusNotImplemented, http.StatusServiceUnavailable} {
176			t.Run(fmt.Sprint(status), func(t *testing.T) {
177				srv := statusServer(t, status, `{"title":"Not Found","detail":"hosted brain is disabled for this repo"}`)
178				h := &HTTPServer{BaseURL: srv.URL, Token: "tok"}
179	
180				_, listErr := h.ListProposals(context.Background(), "repo", "main")
181				if !errors.Is(listErr, ErrProposalQueueUnsupported) {
182					t.Fatalf("ListProposals(%d) = %v; want ErrProposalQueueUnsupported", status, listErr)
183				}
184				if !strings.Contains(listErr.Error(), "hosted brain is disabled for this repo") {
185					t.Fatalf("ListProposals(%d) = %q; the server's explanation was dropped", status, listErr)
186				}
187				_, pubErr := h.PublishProposals(context.Background(), "repo", "main", "old", nil)
188				if !errors.Is(pubErr, ErrProposalQueueUnsupported) {
189					t.Fatalf("PublishProposals(%d) = %v; want ErrProposalQueueUnsupported", status, pubErr)
190				}
191				if !strings.Contains(pubErr.Error(), "hosted brain is disabled for this repo") {
192					t.Fatalf("PublishProposals(%d) = %q; the server's explanation was dropped", status, pubErr)
193				}
194			})
195		}
196	}
197	
198	// SEMANTIC PRESERVATION 3/3 — a 404 on a single proposal stays "already settled",
199	// which is a normal outcome the resolve loop skips past, not a failure.
200	func TestProposalNotFoundStaysNotFound(t *testing.T) {
201		srv := statusServer(t, http.StatusNotFound, `{"title":"Not Found","detail":"proposal p1 was resolved by another member"}`)
202		h := &HTTPServer{BaseURL: srv.URL, Token: "tok"}
203	
204		_, getErr := h.GetProposal(context.Background(), "repo", "main", "prop-1234567890abcdef")
205		if !errors.Is(getErr, ErrProposalNotFound) {
206			t.Fatalf("GetProposal(404) = %v; want ErrProposalNotFound", getErr)
207		}
208		if !strings.Contains(getErr.Error(), "resolved by another member") {
209			t.Fatalf("GetProposal(404) = %q; the server's explanation was dropped", getErr)
210		}
211		_, resErr := h.ResolveProposal(context.Background(), ResolveProposalRequest{
212			RepoID: "repo", Branch: "main", ProposalID: "prop-1234567890abcdef", Decision: Reject, FactsUnchanged: true,
213		})
214		if !errors.Is(resErr, ErrProposalNotFound) {
215			t.Fatalf("ResolveProposal(404) = %v; want ErrProposalNotFound", resErr)
216		}
217		if !strings.Contains(resErr.Error(), "resolved by another member") {
218			t.Fatalf("ResolveProposal(404) = %q; the server's explanation was dropped", resErr)
219		}
220	}
221	
222	// SEMANTIC PRESERVATION, transport half — the dial-retry classifier reads a transport
223	// error, which exists BEFORE any response does. Reading error bodies must leave it
224	// untouched: a local port-table blip is still retried, and a refused connection is
225	// still not.
226	func TestErrorBodyReadingLeavesTheDialClassifierAlone(t *testing.T) {
227		ctx := context.Background()
228		ts := statusServer(t, http.StatusOK, `{"found":false}`)
229		flaky := &flakyDialTransport{failFirst: transientDialRetries, real: http.DefaultTransport}
230		h := &HTTPServer{BaseURL: ts.URL, Token: "tok", Client: &http.Client{Transport: flaky}}
231		if _, _, _, err := h.Current(ctx, "repo", "main"); err != nil {
232			t.Fatalf("Current with transient dial failures = %v; want the retry to still absorb them", err)
233		}
234		if got, want := flaky.callCount(), transientDialRetries+1; got != want {
235			t.Fatalf("round trips = %d, want %d", got, want)
236		}
237	
238		refused := &nonTransientDialTransport{}
239		h2 := &HTTPServer{BaseURL: "http://127.0.0.1:1", Token: "tok", Client: &http.Client{Transport: refused}}
240		if _, _, _, err := h2.Current(ctx, "repo", "main"); err == nil {
241			t.Fatal("Current succeeded against an always-refusing transport")
242		}
243		if refused.calls != 1 {
244			t.Fatalf("round trips = %d, want exactly 1 (a real connectivity error is not retried)", refused.calls)
245		}
246	}
247	
248	// A refusal with nothing to add must not grow a dangling separator.
249	func TestSilentRefusalKeepsACleanMessage(t *testing.T) {
250		srv := statusServer(t, http.StatusBadRequest, "")
251		h := &HTTPServer{BaseURL: srv.URL, Token: "tok"}
252		_, err := h.Advance(context.Background(), "repo", "main", "old", []byte("fact:a\n"))
253		if err == nil {
254			t.Fatal("Advance(400, empty body) produced no error")
255		}
256		if strings.HasSuffix(err.Error(), ": ") || strings.HasSuffix(err.Error(), ":") {
257			t.Fatalf("Advance(400, empty body) = %q; an empty body left a dangling separator", err)
258		}
259	}
