10	func respWith(body string) *http.Response {
11		return &http.Response{Body: io.NopCloser(strings.NewReader(body))}
12	}
13	
14	// The drift this package exists to close: entire-api answers a violated cap with an
15	// actionable RFC 9457 body, and the caller must be able to put that sentence in front
16	// of the user instead of "unexpected status 400 Bad Request".
17	func TestErrorDetailSurfacesHumaDetail(t *testing.T) {
18		got := ErrorDetail(respWith(`{"title":"Bad Request","status":400,"detail":"branch is 600 bytes, limit is 512"}`))
19		if got != "branch is 600 bytes, limit is 512" {
20			t.Fatalf("ErrorDetail = %q; want the server's detail", got)
21		}
22		if s := SuffixFromBody([]byte(`{"detail":"branch is 600 bytes, limit is 512"}`)); s != ": branch is 600 bytes, limit is 512" {
23			t.Fatalf("SuffixFromBody = %q", s)
24		}
25	}
26	
27	// huma puts request-validation specifics in errors[], leaving detail generic, so both
28	// have to survive into the rendered line.
29	func TestErrorDetailKeepsValidationSpecifics(t *testing.T) {
30		got := ErrorDetail(respWith(`{"title":"Unprocessable Entity","detail":"validation failed","errors":[{"message":"expected length <= 512","location":"body.branch"}]}`))
31		if !strings.Contains(got, "validation failed") || !strings.Contains(got, "expected length <= 512") || !strings.Contains(got, "body.branch") {
32			t.Fatalf("ErrorDetail = %q; want detail plus the errors[] specifics", got)
33		}
34	}
