36	func TestErrorDetailFallsBackToTitleThenAlternateKeys(t *testing.T) {
37		if got := ErrorDetail(respWith(`{"title":"Service Unavailable","status":503}`)); got != "Service Unavailable" {
38			t.Fatalf("title fallback = %q", got)
39		}
40		if got := ErrorDetail(respWith(`{"error":"repo not enabled for brain"}`)); got != "repo not enabled for brain" {
41			t.Fatalf("error-key fallback = %q", got)
