48	// An ingress HTML error page is not JSON. It must neither panic nor reach the user as
49	// a wall of markup: the page title is the useful part, and the whole line stays short.
50	func TestErrorDetailHTMLPageIsTitleNotAWallOfMarkup(t *testing.T) {
51		page := "<!DOCTYPE html>\n<html>\n<head><title>502 Bad Gateway</title></head>\n<body>\n<center><h1>502 Bad Gateway</h1></center>\n<hr><center>nginx</center>\n" +
52			strings.Repeat("<div>padding padding padding</div>\n", 40000) + "</body>\n</html>\n"
53		got := ErrorDetail(respWith(page))
54		if got != "502 Bad Gateway" {
55			t.Fatalf("ErrorDetail(html) = %q; want the page title", got)
