59	// A body with no title, no JSON, and no end: bounded, single-line, no panic.
60	func TestErrorDetailUntitledGiantBodyIsBounded(t *testing.T) {
61		got := ErrorDetail(respWith(strings.Repeat("A", 4<<20)))
62		if len([]rune(got)) > maxErrorDetailRunes+1 {
63			t.Fatalf("ErrorDetail length = %d runes; want <= %d", len([]rune(got)), maxErrorDetailRunes+1)
64		}
65		if got == "" {
