70	// Control characters and invalid UTF-8 from a hostile or broken server must not be
71	// pasted into a terminal verbatim.
72	func TestErrorDetailSanitizesControlBytesAndInvalidUTF8(t *testing.T) {
73		got := ErrorDetail(respWith("bad\x00\x1b[31mred\x07\nrequest\xff\xfe here"))
74		if strings.ContainsAny(got, "\x00\x1b\x07\n\r\t") {
75			t.Fatalf("ErrorDetail = %q; control bytes survived", got)
76		}
77		if !strings.Contains(got, "bad") || !strings.Contains(got, "request") {
78			t.Fatalf("ErrorDetail = %q; text was lost", got)
79		}
80		if strings.Contains(got, "���") {
81			t.Fatalf("ErrorDetail = %q; invalid UTF-8 was not cleaned", got)
82		}
83	}
