85	// Nothing to say stays nothing: an empty body must not append a bare ": ".
86	func TestErrorDetailEmptyBodyAddsNothing(t *testing.T) {
87		if got := ErrorDetail(respWith("")); got != "" {
88			t.Fatalf("ErrorDetail(empty) = %q", got)
89		}
90		if got := ErrorDetail(respWith("   \n\t ")); got != "" {
91			t.Fatalf("ErrorDetail(blank) = %q", got)
92		}
93		if got := ErrorSuffix(respWith("")); got != "" {
94			t.Fatalf("ErrorSuffix(empty) = %q; want no separator", got)
95		}
96		if got := ErrorDetail(nil); got != "" {
97			t.Fatalf("ErrorDetail(nil) = %q", got)
98		}
99		if got := ErrorDetail(&http.Response{}); got != "" {
100			t.Fatalf("ErrorDetail(no body) = %q", got)
101		}
102	}
