104	// The read is capped, so a server streaming forever cannot be used to exhaust the
105	// client's memory through its own error path.
106	func TestErrorDetailReadIsCapped(t *testing.T) {
107		counting := &countingReader{}
108		if got := ErrorDetail(&http.Response{Body: io.NopCloser(counting)}); got == "" {
109			t.Fatalf("ErrorDetail read nothing from an endless body")
110		}
111		if counting.n > maxErrorBodyBytes+1024 {
112			t.Fatalf("read %d bytes from an endless body; cap is %d", counting.n, maxErrorBodyBytes)
113		}
114	}
