1	package cli
2	
3	import (
4		"context"
5		"net/http"
6		"net/http/httptest"
7		"strings"
8		"testing"
9	)
10	
11	// `brain publish` already lifted "detail"/"title" out of the server's error envelope,
12	// which is why it never showed the bare-status symptom the fact-set transport did.
13	// What it did NOT do is defend the OTHER shapes an error body arrives in: a proxy's
14	// HTML page (pasted as a 200-character slice of markup) and a peer's control bytes
15	// (pasted into the member's terminal). It also dropped the body entirely on 503, the
16	// one status where the server's own sentence says which of several reasons applies.
17	//
18	// The publish caps the server grew alongside the branch cap — the artifact count and
19	// the manifest reference count — are surfaced, not mirrored: unlike the body-size
20	// ceiling, which the client must project anyway to avoid building a multi-GB buffer,
21	// the client has no independent basis for those counts, and a guessed constant would
22	// refuse bundles the server accepts.
23	
24	const publishTestRepoID = "REDACTED"
25	
26	func publishErrorServer(t *testing.T, status int, body string) *httptest.Server {
27		t.Helper()
28		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
29			w.WriteHeader(status)
30			_, _ = w.Write([]byte(body))
31		}))
32		t.Cleanup(srv.Close)
33		return srv
34	}
35	
36	func publishErr(t *testing.T, status int, body string) string {
37		t.Helper()
38		srv := publishErrorServer(t, status, body)
39		_, err := postBrainArtifacts(context.Background(), srv.URL, publishTestRepoID, "secret", publishRequestBody{})
40		if err == nil {
41			t.Fatalf("postBrainArtifacts(%d) produced no error", status)
42		}
43		return err.Error()
44	}
